CREATE TABLE "LearningPath" ("id" TEXT NOT NULL PRIMARY KEY, "eventId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "skillId" TEXT NOT NULL, "fromLevel" INTEGER NOT NULL, "toLevel" INTEGER NOT NULL, "audience" TEXT NOT NULL, "learningObjectives" TEXT NOT NULL, "masteryThreshold" INTEGER NOT NULL DEFAULT 70, "requiresApproval" BOOLEAN NOT NULL DEFAULT false, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LearningPath_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "LearningPath_skillId_fkey" FOREIGN KEY ("skillId") REFERENCES "Skill"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "LearningPath_eventId_key" ON "LearningPath"("eventId");
CREATE TABLE "LearningEnrollment" ("id" TEXT NOT NULL PRIMARY KEY,"employeeId" TEXT NOT NULL,"pathId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'IN_PROGRESS',"startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" DATETIME,"verifiedAt" DATETIME,"approvalStatus" TEXT NOT NULL DEFAULT 'NOT_REQUIRED',"approvalComment" TEXT,"approvedAt" DATETIME,"readinessBefore" INTEGER NOT NULL,"startingSkills" TEXT NOT NULL,"milestone" TEXT,CONSTRAINT "LearningEnrollment_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "LearningEnrollment_pathId_fkey" FOREIGN KEY ("pathId") REFERENCES "LearningPath"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "LearningEnrollment_employeeId_pathId_key" ON "LearningEnrollment"("employeeId","pathId");
CREATE TABLE "LearningUnit" ("id" TEXT NOT NULL PRIMARY KEY,"pathId" TEXT NOT NULL,"enrollmentId" TEXT,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"type" TEXT NOT NULL,"estimatedMinutes" INTEGER NOT NULL,"order" REAL NOT NULL,"required" BOOLEAN NOT NULL DEFAULT true,"skillId" TEXT NOT NULL,"difficulty" INTEGER NOT NULL,"content" TEXT NOT NULL,"learningObjectives" TEXT NOT NULL,"completionRequirement" TEXT,"masteryPoints" INTEGER NOT NULL DEFAULT 0,"assessmentConfig" TEXT,"isRemediation" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "LearningUnit_pathId_fkey" FOREIGN KEY ("pathId") REFERENCES "LearningPath"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "LearningUnit_enrollmentId_fkey" FOREIGN KEY ("enrollmentId") REFERENCES "LearningEnrollment"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "LearningUnit_pathId_order_idx" ON "LearningUnit"("pathId","order");
CREATE TABLE "LearningUnitProgress" ("id" TEXT NOT NULL PRIMARY KEY,"enrollmentId" TEXT NOT NULL,"unitId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'IN_PROGRESS',"submission" TEXT,"answers" TEXT,"score" REAL,"feedback" TEXT,"attempts" INTEGER NOT NULL DEFAULT 0,"skipped" BOOLEAN NOT NULL DEFAULT false,"startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" DATETIME,CONSTRAINT "LearningUnitProgress_enrollmentId_fkey" FOREIGN KEY ("enrollmentId") REFERENCES "LearningEnrollment"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "LearningUnitProgress_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "LearningUnit"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "LearningUnitProgress_enrollmentId_unitId_key" ON "LearningUnitProgress"("enrollmentId","unitId");
CREATE TABLE "AssessmentResult" ("id" TEXT NOT NULL PRIMARY KEY,"enrollmentId" TEXT NOT NULL,"unitId" TEXT NOT NULL,"score" REAL NOT NULL,"passed" BOOLEAN NOT NULL,"evaluation" TEXT NOT NULL,"submission" TEXT,"answers" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AssessmentResult_enrollmentId_fkey" FOREIGN KEY ("enrollmentId") REFERENCES "LearningEnrollment"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "AssessmentResult_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "LearningUnit"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AssessmentResult_enrollmentId_createdAt_idx" ON "AssessmentResult"("enrollmentId","createdAt");
CREATE TABLE "SkillEvidence" ("id" TEXT NOT NULL PRIMARY KEY,"employeeId" TEXT NOT NULL,"enrollmentId" TEXT NOT NULL,"unitId" TEXT,"skillId" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"level" INTEGER NOT NULL,"score" REAL,"confidence" INTEGER NOT NULL,"summary" TEXT NOT NULL,"verifiedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SkillEvidence_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "SkillEvidence_enrollmentId_fkey" FOREIGN KEY ("enrollmentId") REFERENCES "LearningEnrollment"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "SkillEvidence_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "LearningUnit"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "SkillEvidence_skillId_fkey" FOREIGN KEY ("skillId") REFERENCES "Skill"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "SkillEvidence_enrollmentId_unitId_skillId_key" ON "SkillEvidence"("enrollmentId","unitId","skillId");
CREATE INDEX "SkillEvidence_employeeId_skillId_idx" ON "SkillEvidence"("employeeId","skillId");
